-- 041_terms_acceptance_and_secure_article_submission.sql
--
-- Account-level Terms records and the only public path for submitting a reader
-- article. This migration is additive and idempotent. It does not publish, approve,
-- reject, rewrite or delete existing submissions.
--
-- Security boundary:
--   * auth.uid(), never a client-supplied user id, owns an acceptance/submission.
--   * accepted_at is generated by PostgreSQL.
--   * the server owns the required version and URL.
--   * article status is always Pending and cannot be supplied by Android.
--   * direct INSERT policies are removed so REST cannot bypass the Terms check.

begin;

create table if not exists public.user_terms_acceptances (
    id                uuid primary key default gen_random_uuid(),
    user_id           uuid not null references auth.users(id) on delete cascade,
    terms_version     text not null check (length(btrim(terms_version)) between 1 and 64),
    accepted_at       timestamptz not null default timezone('utc', now()),
    terms_url         text not null check (terms_url ~ '^https://'),
    acceptance_method text not null default 'android_ugc_gate'
                      check (acceptance_method in ('android_ugc_gate')),
    created_at        timestamptz not null default timezone('utc', now()),
    unique (user_id, terms_version)
);

create index if not exists user_terms_acceptances_user_time_idx
    on public.user_terms_acceptances (user_id, accepted_at desc);
create index if not exists user_terms_acceptances_version_idx
    on public.user_terms_acceptances (terms_version, accepted_at desc);

alter table public.user_terms_acceptances enable row level security;

-- A reader can verify their own record. Inserts happen only in
-- accept_current_terms(), while updates/deletes are intentionally unavailable so
-- the compliance history cannot be rewritten from a phone.
drop policy if exists user_terms_acceptances_select_own on public.user_terms_acceptances;
create policy user_terms_acceptances_select_own
    on public.user_terms_acceptances
    for select
    to authenticated
    using (user_id = auth.uid());

drop policy if exists user_terms_acceptances_insert_own on public.user_terms_acceptances;
drop policy if exists user_terms_acceptances_update_own on public.user_terms_acceptances;
drop policy if exists user_terms_acceptances_delete_own on public.user_terms_acceptances;

revoke all on table public.user_terms_acceptances from anon;
revoke insert, update, delete, truncate, references, trigger
    on table public.user_terms_acceptances from authenticated;
grant select on table public.user_terms_acceptances to authenticated;

-- This is the server-side source of truth. A material Terms change gets a new
-- additive migration that replaces these two immutable functions and leaves old
-- acceptance rows intact.
create or replace function public.current_terms_version()
returns text
language sql
immutable
set search_path = pg_catalog, public
as $$
    select '2026-10-26'::text;
$$;

create or replace function public.current_terms_url()
returns text
language sql
immutable
set search_path = pg_catalog, public
as $$
    select 'https://sisir-sinha.github.io/ningshingche/terms-of-use/'::text;
$$;

create or replace function public.has_accepted_current_terms()
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public
as $$
    select auth.uid() is not null
       and exists (
            select 1
              from public.user_terms_acceptances a
             where a.user_id = auth.uid()
               and a.terms_version = public.current_terms_version()
       );
$$;

create or replace function public.accept_current_terms()
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
    me uuid := auth.uid();
    accepted public.user_terms_acceptances;
begin
    if me is null then
        raise exception 'A valid sign-in is required to accept the Terms.'
            using errcode = '42501';
    end if;

    insert into public.user_terms_acceptances (
        user_id, terms_version, terms_url, acceptance_method
    ) values (
        me,
        public.current_terms_version(),
        public.current_terms_url(),
        'android_ugc_gate'
    )
    on conflict (user_id, terms_version) do nothing;

    select a.* into accepted
      from public.user_terms_acceptances a
     where a.user_id = me
       and a.terms_version = public.current_terms_version();

    if accepted.id is null then
        raise exception 'The Terms acceptance could not be recorded.'
            using errcode = 'P0001';
    end if;

    return jsonb_build_object(
        'terms_version', accepted.terms_version,
        'terms_url', accepted.terms_url,
        'accepted_at', accepted.accepted_at
    );
end;
$$;

-- The client supplies article content, never identity, moderation state or the
-- Terms version. Reusing p_id makes a retry idempotent: it returns the original
-- row rather than creating a duplicate submission.
create or replace function public.submit_reader_article(
    p_id uuid,
    p_title text,
    p_content text,
    p_thumbnail text default '',
    p_imgbb_delete_url text default ''
)
returns setof public.submitted_blogs
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
    me uuid := auth.uid();
    profile_row public.profiles;
    clean_title text := btrim(coalesce(p_title, ''));
    clean_content text := btrim(coalesce(p_content, ''));
    clean_plain text;
begin
    if me is null then
        raise exception 'A valid sign-in is required to submit an article.'
            using errcode = '42501';
    end if;

    if not public.has_accepted_current_terms() then
        raise exception 'Accept the current Terms before submitting an article.'
            using errcode = '42501', hint = 'terms_acceptance_required';
    end if;

    if p_id is null then
        raise exception 'A request id is required.' using errcode = '22023';
    end if;

    clean_plain := btrim(regexp_replace(clean_content, '<[^>]*>', ' ', 'g'));
    if length(clean_title) not between 1 and 250 then
        raise exception 'Article title must contain 1 to 250 characters.'
            using errcode = '22023';
    end if;
    if length(clean_plain) < 1 or length(clean_content) > 200000 then
        raise exception 'Article content is empty or too long.'
            using errcode = '22023';
    end if;
    if length(coalesce(p_thumbnail, '')) > 2048
       or length(coalesce(p_imgbb_delete_url, '')) > 2048 then
        raise exception 'An image URL is too long.' using errcode = '22023';
    end if;

    select p.* into profile_row
      from public.profiles p
     where p.id = me;

    if profile_row.id is null then
        raise exception 'Complete your profile before submitting an article.'
            using errcode = '42501', hint = 'profile_required';
    end if;

    if btrim(coalesce(profile_row.first_name, '')) = ''
       or btrim(coalesce(profile_row.last_name, '')) = ''
       or btrim(coalesce(profile_row.avatar_url, '')) = ''
       or btrim(coalesce(profile_row.about, '')) = ''
       or btrim(coalesce(profile_row.phone, '')) = ''
       or btrim(coalesce(profile_row.address, '')) = ''
       or btrim(coalesce(profile_row.facebook_id, '')) = '' then
        raise exception 'Complete your profile before submitting an article.'
            using errcode = '42501', hint = 'profile_required';
    end if;

    insert into public.submitted_blogs (
        id, title, designation, address, phone, thumbnail, imgbb_delete_url,
        writer_name, writer_designation, writer_profile_image, writer_email,
        writer_facebook, content_title, content, status, converted_blog_id, user_id
    ) values (
        p_id,
        clean_title,
        coalesce(profile_row.designation, ''),
        coalesce(profile_row.address, ''),
        coalesce(profile_row.phone, ''),
        btrim(coalesce(p_thumbnail, '')),
        btrim(coalesce(p_imgbb_delete_url, '')),
        coalesce(
            nullif(btrim(concat_ws(' ', profile_row.first_name, profile_row.last_name)), ''),
            nullif(btrim(profile_row.name), ''),
            'Reader'
        ),
        coalesce(profile_row.designation, ''),
        coalesce(profile_row.avatar_url, ''),
        coalesce(nullif(btrim(profile_row.email), ''), auth.jwt() ->> 'email', ''),
        coalesce(profile_row.facebook_id, ''),
        clean_title,
        clean_content,
        'Pending',
        null,
        me
    )
    on conflict (id) do nothing;

    return query
        select s.*
          from public.submitted_blogs s
         where s.id = p_id
           and s.user_id = me;

    if not found then
        raise exception 'That submission id is already in use.' using errcode = '23505';
    end if;
end;
$$;

-- Remove every public/client insert door created by historical setup scripts.
-- Dashboard-specific policies from migration 004 are untouched.
drop policy if exists submissions_public_insert on public.submitted_blogs;
drop policy if exists submitted_blogs_insert_own on public.submitted_blogs;

revoke all on function public.current_terms_version() from public;
revoke all on function public.current_terms_url() from public;
revoke all on function public.has_accepted_current_terms() from public;
revoke all on function public.accept_current_terms() from public;
revoke all on function public.submit_reader_article(uuid, text, text, text, text) from public;

revoke all on function public.accept_current_terms() from anon;
revoke all on function public.has_accepted_current_terms() from anon;
revoke all on function public.submit_reader_article(uuid, text, text, text, text) from anon;

grant execute on function public.current_terms_version() to anon, authenticated;
grant execute on function public.current_terms_url() to anon, authenticated;
grant execute on function public.has_accepted_current_terms() to authenticated;
grant execute on function public.accept_current_terms() to authenticated;
grant execute on function public.submit_reader_article(uuid, text, text, text, text)
    to authenticated;

comment on table public.user_terms_acceptances is
    'Immutable account-level evidence of explicit UGC Terms acceptance.';
comment on function public.submit_reader_article(uuid, text, text, text, text) is
    'Authenticated, Terms-gated reader article submission; always creates Pending content.';

commit;
